import { ToggleTokenBalanceVisibility } from '~/features/toggle-switches/ui/toggle-token-balance-visiblity';
import { useComBankInfo } from '~/entities/comcode/lib/use-com-bank-info';
import { useExchangeNavigation } from '~/entities/exchange/lib/use-exchange-navigation';
import { TOKEN_LABEL, TokenItem } from '~/entities/pin/api/dtos/types';
import { useGetUserInfoQuery } from '~/entities/user/api/use-get-cstmr-query';
import { findTokenItemByType } from '~/entities/user/lib/token-utils';
import { TokenItemType, TrnscTypeCd } from '~/shared/api/dtos/enums';
import { appConfig } from '~/shared/config';
import i18n from '~/shared/i18n/i18n';
import { PATHS } from '~/shared/routes/paths';
import { ToggleSwitchSection } from '~/shared/ui/toggle-switch/toggle-switch-section';

type TokenInfoProps = {
  close: () => void;
  tokenList?: TokenItem[];
};

export const TokenInfo = ({ close, tokenList }: TokenInfoProps) => {
  const { data: userRes } = useGetUserInfoQuery();
  const { navigateToExchange } = useExchangeNavigation();
  const item = tokenList?.[0] ?? findTokenItemByType(userRes?.tbCstmrMastr?.tokenList, TokenItemType.DC1);
  const { shortBankName } = useComBankInfo(item?.bankCd ?? appConfig.BANK_CODE ?? '');

  const handleClickConvertToToken = () => {
    if (!item) {
      throw new Error('Item is not found');
    }
    close();
    navigateToExchange({
      path: `${PATHS.exchange.root}`,
      item,
      trnscTypeCd: TrnscTypeCd.전환입금,
    });
  };

  return (
    <div className="env-bottom mb-[30px] flex w-full flex-col items-center">
      <div className="btm-sheet-top w-full">
        <h2 className="ml-[30px] mr-[30px] flex flex-col text-[18px] leading-[36px]">
          {TOKEN_LABEL[TokenItemType.DC1]} | {shortBankName}
          <button
            className={`wallet-account no-btn dark text-left text-[14px] font-normal ${item?.bankCd ?? appConfig.BANK_CODE}`}
          >
            {shortBankName} {userRes?.tbCstmrMastr?.aliasNm ?? ''}
          </button>
        </h2>
      </div>
      <div className="btm-sheet-list mt-[20px] w-full">
        <div className="qr-pay-info">
          <button type="button" className="menu-btn" onClick={handleClickConvertToToken}>
            <span className="menu-btn-text">{i18n.t('convertToToken')}</span>
          </button>
          <ToggleSwitchSection label={i18n.t('hideBalance')}>
            <ToggleTokenBalanceVisibility />
          </ToggleSwitchSection>
        </div>
      </div>
    </div>
  );
};
