import { useEffect, useRef } from 'react';
import { SelectBottomSheetProps } from './base';
import { useSelectBottomSheet } from './use-select-bottom-sheet';

type SelectBottomSheetComponentProps<T> = {
  isOpen: boolean;
} & SelectBottomSheetProps<T>;

export function SelectBottomSheet<T>({ isOpen, ...props }: SelectBottomSheetComponentProps<T>) {
  const { openSelectBottomSheet } = useSelectBottomSheet<T>();
  const wasOpenRef = useRef(false);

  useEffect(() => {
    if (isOpen && !wasOpenRef.current) {
      wasOpenRef.current = true;

      const timer = setTimeout(() => {
        openSelectBottomSheet({
          ...props,
        });
      }, 0);

      return () => clearTimeout(timer);
    }

    if (!isOpen) {
      wasOpenRef.current = false;
    }
  }, [isOpen, openSelectBottomSheet, props]);

  return null;
}
