import { useQueryClient } from '@tanstack/react-query';
import { queries } from '~/shared/api/query-keys';

export const useClearPayment = () => {
  const queryClient = useQueryClient();

  const clearPayment = () => {
    queryClient.removeQueries({ queryKey: queries.payment._def });

    queryClient.invalidateQueries({
      queryKey: queries.payment._def,
      refetchType: 'all',
    });
  };

  return { clearPayment };
};
