import { memo } from 'react';
import { useGenerateTxCodeWithPinAuth } from '~/entities/payment/api/hooks/use-generate-tx-code-with-pin-auth';
import { useTxCode } from '~/entities/payment/api/hooks/use-tx-code';
import { VoucherItemDTO } from '~/entities/voucher/api/dtos/voucher-item';
import { useSelectedVoucher } from '~/entities/voucher/api/hooks/use-selected-voucher';
import { useVoucherOptions } from '~/entities/voucher/lib/use-voucher-options';
import i18n from '~/shared/i18n/i18n';
import { SelectStyle } from '~/shared/ui/selects/base/types';
import { SelectBottomSheet } from '~/shared/ui/selects/select-bottom-sheet';

export const PaymentSelectBottomSheet = memo(function PaymentSelectBottomSheet({
  isOpen,
  onClose,
}: {
  isOpen: boolean;
  onClose: () => void;
}) {
  const { options, getSelectedOption } = useVoucherOptions();
  const { data } = useTxCode();
  const txData = data?.tbPayMastr;

  const { generateTxCodeWithPinAuth } = useGenerateTxCodeWithPinAuth();
  const { setSelectedVoucher } = useSelectedVoucher();

  return (
    <SelectBottomSheet<VoucherItemDTO>
      isOpen={isOpen}
      onClose={onClose}
      title={i18n.t('selectVoucherBenefit')}
      options={options}
      selectedOption={getSelectedOption(txData?.vouchId ?? null)}
      valueKey="vouchId"
      selectStyle={SelectStyle.RADIO}
      shouldShowConfirmButton={true}
      confirmButtonLabel={i18n.t('confirm')}
      onConfirm={({ selectedOption }) => {
        setSelectedVoucher(selectedOption.value);
        generateTxCodeWithPinAuth({
          vouchId: selectedOption.value?.vouchId ?? '',
          vouchAmt: selectedOption.value?.pymntAmt?.toString() ?? '',
          vouchAddres: selectedOption.value?.contractAdres ?? '',
          vouchBankCode: selectedOption.value?.vouchBankCode ?? '',
          insttWalletAdres: selectedOption.value?.insttWalletAdres ?? '',
          vouchTypeNm: selectedOption.value?.vouchTyNm ?? '',
          vouchNm: selectedOption.value?.vouchNm ?? '',
          vouchTyCd: selectedOption.value?.vouchTyCd ?? '',
        });
        onClose();
      }}
    />
  );
});
