import { useMutation, useQueryClient } from '@tanstack/react-query';
import { GenerateTxCodeRequestDTO, GenerateTxCodeResponseDTO } from '~/entities/payment/api/dtos/types';
import { paymentApi } from '~/entities/payment/api/payment-api';
import { CBDCAxiosError } from '~/shared/@types/error';
import { MutationOptions } from '~/shared/@types/query';
import { queries } from '~/shared/api/query-keys';

export const useGenerateTxCode = (
  options?: MutationOptions<GenerateTxCodeRequestDTO, CBDCAxiosError, GenerateTxCodeResponseDTO>,
) => {
  const queryClient = useQueryClient();

  return useMutation({
    ...options,
    mutationKey: queries.payment.generateTxCode.queryKey,
    mutationFn: ({ tbPayMastr }: GenerateTxCodeRequestDTO) => paymentApi.generateTxCode({ tbPayMastr }),
    onSuccess: (newTxCode, variables) => {
      queryClient.setQueryData(queries.payment.generateTxCode.queryKey, newTxCode);

      // queryClient.invalidateQueries({
      //   queryKey: queries.payment.generateTxCode.queryKey,
      //   refetchType: 'all',
      // });

      options?.onSuccess?.(newTxCode, variables, undefined, undefined as any);
    },
  });
};
