import { TxCodeParams } from '~/entities/payment/api/dtos/types';
import { usePinBottomSheet } from '~/shared/lib/hooks/use-pin-bottom-sheet';
import { overlay } from '~/shared/lib/overlay';
import { useGenerateTxCode } from './use-generate-tx-code';

export const useGenerateTxCodeWithPinAuth = () => {
  const { openPinBottomSheet } = usePinBottomSheet();
  const { mutateAsync: generateTxCodeAsync } = useGenerateTxCode();

  const generateTxCodeWithPinAuth = async (params: TxCodeParams) => {
    openPinBottomSheet((close) => {
      close();
      setTimeout(async () => {
        generateTxCodeAsync({ tbPayMastr: params });
        overlay.closeAll();
      }, 0);
    });
  };

  return { generateTxCodeWithPinAuth };
};
