import { memo, useCallback } from 'react';
import { useStore } from '~/app/store/store';
import { useComBankInfo } from '~/entities/comcode/lib/use-com-bank-info';
import { useTokenInfoBottomSheet } from '~/entities/payment/lib/use-token-info-bottom-sheet';
import { TokenItem } from '~/entities/pin/api/dtos/types';
import { useGetUserInfoQuery } from '~/entities/user/api/use-get-cstmr-query';
import { findTokenItemByType } from '~/entities/user/lib/token-utils';
import { TokenItemType } from '~/shared/api/dtos/enums';
import { appConfig } from '~/shared/config';
import i18n from '~/shared/i18n/i18n';

type TokenInfoButtonProps = {
  tokenList?: TokenItem[];
};

export const TokenInfoButton = memo(function TokenInfoButton({ tokenList }: TokenInfoButtonProps) {
  const { data: userRes } = useGetUserInfoQuery({ staleTime: 0 });
  const item = tokenList?.[0] ?? findTokenItemByType(userRes?.tbCstmrMastr?.tokenList, TokenItemType.DC1);
  const { shortBankName } = useComBankInfo(item?.bankCd ?? appConfig.BANK_CODE ?? '');
  const { openBottomSheet: openTokenInfoBottomSheet } = useTokenInfoBottomSheet({ tokenList });
  const isHideBalance = useStore((state) => state.appConfigSlice.isHideBalance);
  const displayBalance = isHideBalance
    ? i18n.t('balanceHidden')
    : `${item?.amt.toLocaleString() ?? 0} ${i18n.t('won')}`;

  const handleClickTokenInfo = useCallback(() => {
    openTokenInfoBottomSheet();
  }, [openTokenInfoBottomSheet]);

  return (
    <button type="button" className="pay-info" onClick={handleClickTokenInfo}>
      <p>
        {/* {TOKEN_LABEL[TokenItemType.DC1]} | {shortBankName} */}
        {shortBankName} | {userRes.tbCstmrMastr?.dfltAliasNm}
      </p>
      <p className="balance" style={{ display: 'flex', justifyContent: 'space-between' }}>
        <span style={{ fontSize: 'var(--font-size-14)', alignContent: 'end', fontWeight: '400' }}>보유 잔액</span>
        <span>{displayBalance}</span>
      </p>
    </button>
  );
});
