import { TokenInfo } from '~/entities/payment/ui/token-info';
import { TokenItem } from '~/entities/pin/api/dtos/types';
import { overlay } from '~/shared/lib/overlay';
import { BottomSheet } from '~/shared/ui/bottom-sheets/bottom-sheet';

type UseTokenInfoBottomSheetParams = {
  tokenList?: TokenItem[];
};

export const useTokenInfoBottomSheet = ({ tokenList }: UseTokenInfoBottomSheetParams = {}) => {
  const openBottomSheet = () => {
    overlay.exclusiveOpen(({ isOpen, close, unmount }) => {
      return (
        <BottomSheet afterLeave={unmount} open={isOpen} onClose={close}>
          <TokenInfo close={close} tokenList={tokenList} />
        </BottomSheet>
      );
    });
  };

  return { openBottomSheet, closeBottomSheet: overlay.closeAll };
};
